//! The panel's wire contract, `sa.funnel.v1`, generated from `contracts/proto/sa/v1`.
//!
//! Every message has prost (binary) and serde (protojson, via pbjson) impls; the HTTP
//! ingest speaks the latter. Nothing here validates beyond the JSON shape: what a field may
//! hold is the panel's to check.
//!
//! Also [`concierge::v1`]: the part of concierge's gRPC contract the sign-in uses, and
//! [`scope::v1`]: banking's ScopeLedger, which the panel issues invoices through.

/// `package sa.v1`.
// Generated by prost and pbjson at build time: its style is theirs, and a lint there has
// no fix we could keep (the next build writes it again).
#[allow(clippy::all)]
pub mod v1 {
	include!(concat!(env!("OUT_DIR"), "/sa.v1.rs"));
	include!(concat!(env!("OUT_DIR"), "/sa.v1.serde.rs"));
}

/// `package concierge.v1`, vendored from concierge (`contracts/proto/concierge`): the
/// panel signs its users in as a relying party of concierge. Clients for the panel, servers
/// for the tests' stand-in concierge.
pub mod concierge {
	// Generated by tonic-prost-build at build time; the same reasoning as `v1` above.
	#[allow(clippy::all)]
	pub mod v1 {
		include!(concat!(env!("OUT_DIR"), "/concierge.v1.rs"));
	}
}

/// `package scope.v1`, vendored from banking (`contracts/proto/scope`): the panel's invoices
/// in the scope `sa`. Clients only; the servers too under the `testing` feature, for the
/// tests' stand-in ledger.
pub mod scope {
	// Generated by tonic-prost-build at build time; the same reasoning as `v1` above.
	#[allow(clippy::all)]
	pub mod v1 {
		include!(concat!(env!("OUT_DIR"), "/scope.v1.rs"));
	}
}

pub use pbjson_types;

/// The `schema` every `sa.funnel.v1` event carries.
pub const SCHEMA: &str = "sa.funnel.v1";

#[cfg(test)]
mod tests {
	use super::v1::{Event, PaymentReceivedV1};

	#[test]
	fn protojson_in_both_spellings() {
		let camel: Event = serde_json::from_value(serde_json::json!({
			"id": "0192f0c1-7b3a-7c2e-9d4f-1a2b3c4d5e6f",
			"schema": "sa.funnel.v1",
			"type": "lead.created",
			"typeVersion": 1,
			"occurredAt": "2026-09-30T10:00:00Z",
			"source": {"kind": "site", "id": "aquafix"},
			"subject": {"brandId": "aquafix", "leadId": "L-1"},
			"properties": {"channel": "form"},
			"pii": {"phone": "+33 6 00 00 00 00"}
		}))
		.unwrap();
		let snake: Event = serde_json::from_value(serde_json::json!({
			"id": "0192f0c1-7b3a-7c2e-9d4f-1a2b3c4d5e6f",
			"schema": "sa.funnel.v1",
			"type": "lead.created",
			"type_version": 1,
			"occurred_at": "2026-09-30T10:00:00Z",
			"source": {"kind": "site", "id": "aquafix"},
			"subject": {"brand_id": "aquafix", "lead_id": "L-1"},
			"properties": {"channel": "form"},
			"pii": {"phone": "+33 6 00 00 00 00"}
		}))
		.unwrap();
		assert_eq!(camel, snake);
		assert_eq!(camel.occurred_at.unwrap().seconds, 1_790_762_400);
		assert_eq!(camel.subject.unwrap().lead_id.as_deref(), Some("L-1"));
	}

	#[test]
	fn int64_as_string_or_number_and_unknown_fields_refused() {
		let a: PaymentReceivedV1 = serde_json::from_value(serde_json::json!({"billed": "12000", "commission": 1800, "currency": "EUR"})).unwrap();
		assert_eq!((a.billed, a.commission), (12_000, 1_800));
		assert!(serde_json::from_value::<PaymentReceivedV1>(serde_json::json!({"billed": 1, "tip": 2})).is_err());
	}
}
